// TH15 Extra / Boss5 nonspell, rank4 (source !O path).
// Source: st07bs.ecl.txt:654-726 Boss5; closure:
//   st07bs2.ecl.txt:108-129 BossB5, default.ecl.txt:37-49 BossItemPhase3.
// Shell: invulnerable real boss carries the phase segment (validation.md permits
// "也可由真实Boss承载段"); card frame 0 = main spawn, the phase clock starts a
// few frames later; +120 after that = Boss5 entry.

const TIME_LIMIT: int = 4324;   // 120 opening + 4200 source window + 4 startup
const OPENING_BUFFER: int = 120;

// Copied from transcribe/th15/touhou-bullets.ecl: source type9 -> TH15_KUNAI.
const TH15_KUNAI: int = 496;

// st07bs.ecl.txt:8-39 common Boss entry state: hurtbox 40, hitbox 48, init (0,128).
// setInvuln(120) is replaced by the shell's set_invuln(65535).
async sub boss_main() {
    set_invuln(65535);
    set_hitbox(48fx);
    set_hurtbox(40fx);
    // 657 lifeSet(20500): spawn hp below. 673 timerReset + 710 setInterrupt(0,3500,4200):
    // represented by the phase clock (TIME_LIMIT) and hp threshold 3500.
    phase_begin(0, boss5_pattern, TIME_LIMIT, 3500);
    wait_spell();
    return;
}

// st07bs2.ecl.txt:108-129 BossB5, the enmCall($GI0,"BossB5") dependency.
