// ---- moveRand(60, 4, 1.9) ------------------------------------------------
// transcribe/th16/movement.md recipe. Boss5:695 moveLimitReset() cancels the
// per-frame clamp before this loop, so the helper does not clamp; the direction
// pick keeps the card's entry limit (0,128,280,64) regions: x +-70, y 112..144.
// int slot0 = next source movement step; fx0/fx1 = cos/sin of the fixed direction.
sub boss5_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 {
        speed = ((60 - k) as fx / 60) * 1.9fx;
    }
    move_vel_xy(0, self_fx(0) * speed, self_fx(1) * speed, EASE_LINEAR);
}

sub boss5_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    boss5_arm_next_step();
}

sub boss5_move_rand() {
    // Source 412 direction pick. RANDRAD is a signed full circle (one draw).
    var r: int = rand(65536) - 32768;
    var a: int = 0;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +-pi/2 guard, 0.05rad -> nearest BAM boundaries.
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    boss5_begin_angle(a as angle);
}

// Every source wait inside moveRand is also a movement tick.
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        boss5_arm_next_step();
    }
}

// st07bs.ecl.txt:728-763 Boss5_at. etAim(0,10), etCount(15,4), etSprite(9,4),
// etSpeed(1.4,1.4), etDist(24). The EX record etEx(0,0,2,1,-999999,-999999,-999999)
// is type2 ANIM: birth back-displacement 4*1.4=5.6, so net birth distance 18.4px.
// mode10 with M=4 has even layers at +H, odd at -H, H=(q/2+1/2)*1deg (91/273 BAM).
// Each layer is one 15-way ring; odd layers enumerate the same point set in reverse
// creation order. No random/EX/task/capacity consumer depends on that order.
async sub boss5_at() {
    sh_reset(0);
    sh_sprite(0, TH15_KUNAI, 4);
    sh_ring(0, 1);
    sh_count(0, 15, 1);
    sh_speed(0, 1.4fx, 0fx);
    sh_dist(0, 18.4fx);

    var base: int = rand(65536) - 32768;       // 739 %RANDRAD
    var n: int = 10;                           // 740 $B
    while n > 0 {
        sh_angle(0, (base + 91) as angle, 0deg);
        sh_fire(0);
        sh_angle(0, (base - 91) as angle, 0deg);
        sh_fire(0);
        sh_angle(0, (base + 273) as angle, 0deg);
        sh_fire(0);
        sh_angle(0, (base - 273) as angle, 0deg);
        sh_fire(0);
        base = base + 40503;                   // 745 +3.883222 rad
        wait(5);
        n = n - 1;
    }
    wait(10);

    base = rand(65536) - 32768;                // 751 %RANDRAD
    n = 10;                                    // 752 $D
    while n > 0 {
        sh_angle(0, (base + 91) as angle, 0deg);
        sh_fire(0);
        sh_angle(0, (base - 91) as angle, 0deg);
        sh_fire(0);
        sh_angle(0, (base + 273) as angle, 0deg);
        sh_fire(0);
        sh_angle(0, (base - 273) as angle, 0deg);
        sh_fire(0);
        base = base - 40503;                   // 757 -3.883222 rad
        wait(5);
        n = n - 1;
    }
}

// ---- Boss5 main -----------------------------------------------------------
async sub boss5_pattern() {
    wait(OPENING_BUFFER);

    // 659 etClear(640): no prior bullets in the standalone card; keep the clear.
    clear_bullets();
    // 666 enmCall($GI0,"BossB5"): the other boss; spawned at its movePos origin.
    _ = spawn_enemy(-192fx, -64fx, 17001, 0, 0, 0, boss_b_motion);
    // 673 timerReset: the phase clock above is the card's timer base.
    // 674 killAllAsync: no prior same-owner async task exists in this card.
    // 675 enmKillAll: no regular enemies exist here (the two bosses are the targets).
    // 676-681 etClear(640): second entry clear, in source order.
    clear_bullets();
    // 682 spellEnd: no previous spell binds this slot; 683 funcSet(0): no callback here;
    // 684 laserCancel: no laser exists in this card.
    // 686-688 moveVel/moveVelTime/movePosTime(0,...): stop velocity and position tweens.
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    move_to(0, $self_x, $self_y, EASE_LINEAR);
    // 695 moveLimitReset: the per-frame clamp is gone; moveRand helper keeps only
    // the entry limit's direction thresholds (see helper comments).
    // 696 movePosTime(60,4,80,128)
    move_to(60, 80fx, 128fx, EASE_QUAD_OUT);
    wait(60);
    // 698 movePosTime(120,1,192,-80)
    move_to(120, 192fx, -80fx, EASE_QUAD_IN);
    wait(120);
    // 708 movePos(0,128)
    move_to(0, 0fx, 128fx, EASE_LINEAR);
    wait(60);                                  // 714

    // 717/724 Boss5_1504 loop.
    loop {
        spawn boss5_at();                      // 719 async
        wait(100);                             // 720
        boss5_move_rand();                     // 721 moveRand(60,4,1.9f)
        card_wait(60);                         // 722
    }
}

sub main() {
    // 657 lifeSet(20500); common entry position (0,128).
    _ = spawn_enemy(0fx, 128fx, 20500, 0, 0, 0, boss_main);
    loop { wait(600); }
}
